mapper.sql:
SELECT l.link_id, l.merchant_id, l.merchant_order_no, l.link_name, l.description, l.merchant_display_name, l.currency, l.amount AS amount, l.currency_exponent, l.locale, () AS status, COALESCE(s.checkout_status, 'PENDING') AS payment_status, COALESCE(s.attempt_count, 0) AS attempt_count, locator.transaction_id, locator.transaction_date_time, l.expire_time, l.create_time, s.paid_time, l.created_app_code, l.created_by, l.disable_reason, l.version
LEFT JOIN transaction_locator locator ON locator.transaction_id = s.latest_transaction_id AND locator.merchant_id = l.merchant_id AND locator.merchant_order_no = l.merchant_order_no
ORDER BY l.id DESC LIMIT #{query.pageSize} OFFSET #{offset}
